import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, KeyboardEvent } from 'react';
import { Link } from 'react-router-dom';
import { Bot, Copy, History, MessageSquarePlus, RefreshCw, Send, Trash2, X } from 'lucide-react';
import { api, apiStream, errMsg } from '../api';
import { useAuth } from '../auth';
import type { PolicyV3 } from '../types3';

/** CoverMate AI chat window. Every answer is generated by the LLM that the backend is configured for; this component only displays it.
 *  Nothing here contains answer text. The welcome message and suggested questions are interface copy, not model output. */
export const UNAVAILABLE = 'CoverMate AI is temporarily unavailable. Please try again later.';
const WELCOME = "Hi! I'm CoverMate AI. Insurance terms can be confusing, but don't worry. Ask me anything about your coverage, policy, premiums, exclusions, or claims. I'll explain everything in simple language.";
const SUGGESTIONS = ['What is insurance?', 'Why do insurance companies collect premiums?', 'What is the difference between insurance and warranty?', 'Why might an insurance claim be rejected?', 'What is a deductible?'];

interface Msg { key: string; role: 'user' | 'ai'; content: string; notice?: string | null; error?: boolean; pending?: boolean }
interface Focus { policy_number: string | null; claim_number: string | null; policy_id: number | null; claim_id: number | null }
interface ConvSummary { id: string; title: string; updated_at: string; message_count: number }
interface StoredMsg { id: number; role: 'user' | 'assistant'; content: string; notice?: string | null }

let seq = 0;
const k = () => `m${++seq}`;

/** Minimal SSE reader: yields {event, data} for each blank-line separated block. */
async function* sse(res: Response): AsyncGenerator<{ event: string; data: any }> {
  const reader = res.body?.getReader();
  if (!reader) return;
  const dec = new TextDecoder();
  let buf = '';
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let i: number;
    while ((i = buf.indexOf('\n\n')) >= 0) {
      const block = buf.slice(0, i); buf = buf.slice(i + 2);
      let event = 'message'; let data = '';
      for (const line of block.split('\n')) {
        if (line.startsWith('event:')) event = line.slice(6).trim();
        else if (line.startsWith('data:')) data += line.slice(5).trim();
      }
      if (data) { try { yield { event, data: JSON.parse(data) }; } catch { /* ignore malformed block */ } }
    }
  }
}

export default function CoverMate() {
  const { user } = useAuth();
  const [open, setOpen] = useState(false);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [text, setText] = useState('');
  const [busy, setBusy] = useState(false);
  const [convId, setConvId] = useState<string | null>(null);
  const [focus, setFocus] = useState<Focus | null>(null);
  const [available, setAvailable] = useState<boolean | null>(null);
  const [policies, setPolicies] = useState<PolicyV3[]>([]);
  const [policyId, setPolicyId] = useState('');
  const [history, setHistory] = useState<ConvSummary[] | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [copied, setCopied] = useState('');
  const bodyRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fabRef = useRef<HTMLButtonElement>(null);
  const abort = useRef<AbortController | null>(null);
  const isStudent = user?.role === 'student';

  useEffect(() => {
    if (!open || available !== null) return;
    api<{ available: boolean }>('/ai/chat/status').then(s => setAvailable(s.available)).catch(() => setAvailable(false));
    if (isStudent) api<PolicyV3[]>('/v2/policies').then(p => setPolicies(p.filter(x => x.status === 'Active'))).catch(() => undefined);
  }, [open, available, isStudent]);
  useEffect(() => { if (open) inputRef.current?.focus(); }, [open]);
  useEffect(() => { const el = bodyRef.current; if (el) el.scrollTop = el.scrollHeight; }, [msgs, open, showHistory]);
  useEffect(() => () => abort.current?.abort(), []);

  const close = useCallback(() => { setOpen(false); setTimeout(() => fabRef.current?.focus(), 0); }, []);

  const send = useCallback(async (raw: string, opts: { retry?: boolean; policy?: number } = {}) => {
    const message = raw.trim();
    if (!message || busy) return;
    setBusy(true); setShowHistory(false);
    const aiKey = k();
    setMsgs(m => {
      let base = m;
      if (opts.retry) {  // drop the last answer, then the question that produced it; the server does the same
        if (base.at(-1)?.role === 'ai') base = base.slice(0, -1);
        if (base.at(-1)?.role === 'user') base = base.slice(0, -1);
      }
      return [...base, { key: k(), role: 'user', content: message }, { key: aiKey, role: 'ai', content: '', pending: true }];
    });
    setText('');
    abort.current = new AbortController();
    const body: Record<string, unknown> = { message };
    if (convId) body.conversation_id = convId;
    if (opts.retry) body.retry = true;
    const pid = opts.policy ?? (policyId ? Number(policyId) : undefined);
    if (pid) body.policy_id = pid;
    const patch = (p: Partial<Msg>) => setMsgs(m => m.map(x => (x.key === aiKey ? { ...x, ...p } : x)));
    try {
      const res = await apiStream('/ai/chat/stream', body);
      let acc = '';
      for await (const ev of sse(res)) {
        if (ev.event === 'meta') { setConvId(ev.data.conversation_id); setFocus(ev.data.focus ?? null); }
        else if (ev.event === 'delta') { acc += ev.data.text; patch({ content: acc, pending: false }); }
        else if (ev.event === 'done') { patch({ content: ev.data.message.content, notice: ev.data.message.notice, pending: false }); setHistory(null); }
        else if (ev.event === 'error') { patch({ content: ev.data.message || UNAVAILABLE, error: true, pending: false }); }
      }
      setMsgs(m => m.map(x => (x.key === aiKey && x.pending ? { ...x, content: UNAVAILABLE, error: true, pending: false } : x)));
    } catch (e) {
      const status = (e as { status?: number }).status;
      patch({ content: status === 503 || status === 0 ? UNAVAILABLE : errMsg(e), error: true, pending: false });
      if (status === 503) setAvailable(false);
    } finally { setBusy(false); inputRef.current?.focus(); }
  }, [busy, convId, policyId]);

  const retry = () => {
    const lastUser = [...msgs].reverse().find(m => m.role === 'user');
    if (lastUser) void send(lastUser.content, { retry: true });
  };
  const newChat = () => { abort.current?.abort(); setMsgs([]); setConvId(null); setFocus(null); setShowHistory(false); setBusy(false); };
  const clearChat = async () => {
    if (convId) { try { await api(`/ai/chat/conversations/${convId}/clear`, { method: 'POST' }); } catch { /* local clear still applies */ } }
    setMsgs([]); setFocus(null); setHistory(null);
  };
  const openHistory = async () => {
    setShowHistory(s => !s);
    if (history === null) { try { setHistory(await api<ConvSummary[]>('/ai/chat/conversations')); } catch { setHistory([]); } }
  };
  const load = async (id: string) => {
    try {
      const c = await api<{ id: string; messages: StoredMsg[] }>(`/ai/chat/conversations/${id}`);
      setConvId(c.id); setFocus(null); setShowHistory(false);
      setMsgs(c.messages.map(m => ({ key: k(), role: m.role === 'user' ? 'user' : 'ai', content: m.content, notice: m.notice })));
    } catch (e) { setMsgs(m => [...m, { key: k(), role: 'ai', content: errMsg(e), error: true }]); setShowHistory(false); }
  };
  const copy = async (m: Msg) => { try { await navigator.clipboard.writeText(m.content); setCopied(m.key); setTimeout(() => setCopied(''), 1500); } catch { /* clipboard blocked */ } };
  const submit = (e: FormEvent) => { e.preventDefault(); void send(text); };
  const onKey = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); void send(text); }
  };

  if (!user) return null;
  if (!open) {
    return <button ref={fabRef} type="button" className="cm-fab" aria-label="Open CoverMate AI chat" onClick={() => setOpen(true)}><Bot size={22} aria-hidden="true" /><span>CoverMate AI</span></button>;
  }
  const lastAi = [...msgs].reverse().find(m => m.role === 'ai');
  return (
    <section className="cm-panel" role="dialog" aria-label="CoverMate AI chat" onKeyDown={e => { if (e.key === 'Escape') close(); }}>
      <header className="cm-head">
        <Bot size={24} aria-hidden="true" />
        <div className="grow"><strong>CoverMate AI</strong><small>Insurance explained in simple words</small></div>
        <button type="button" className="cm-icon-btn" onClick={() => void openHistory()} aria-label="Chat history" aria-pressed={showHistory} title="Chat history"><History size={18} aria-hidden="true" /></button>
        <button type="button" className="cm-icon-btn" onClick={newChat} aria-label="New conversation" title="New conversation"><MessageSquarePlus size={18} aria-hidden="true" /></button>
        <button type="button" className="cm-icon-btn" onClick={() => void clearChat()} aria-label="Clear conversation" title="Clear conversation" disabled={msgs.length === 0}><Trash2 size={18} aria-hidden="true" /></button>
        <button type="button" className="cm-icon-btn" onClick={close} aria-label="Close chat"><X size={20} aria-hidden="true" /></button>
      </header>
      {isStudent && policies.length > 0 && (
        <div className="cm-meta">
          <label htmlFor="cm-policy" style={{ margin: 0, fontWeight: 500 }}>Policy</label>
          <select id="cm-policy" value={policyId} onChange={e => setPolicyId(e.target.value)} disabled={busy}>
            <option value="">All my policies</option>
            {policies.map(p => <option key={p.id} value={p.id}>{p.policy_number}{p.asset_name ? ` (${p.asset_name})` : ''}</option>)}
          </select>
          <button type="button" className="secondary sm" disabled={busy || !policyId || available === false} onClick={() => void send('Explain my entire policy in simple language.', { policy: Number(policyId) })}>Explain this policy</button>
        </div>
      )}
      <div className="cm-body" ref={bodyRef} role="log" aria-live="polite" aria-label="Conversation">
        {showHistory ? (
          <div>
            <strong>Earlier conversations</strong>
            {history === null ? <p className="muted">Loading…</p> : history.length === 0 ? <p className="muted">No saved conversations yet.</p> : (
              <ul style={{ listStyle: 'none', padding: 0, display: 'grid', gap: '.4rem' }}>
                {history.map(h => <li key={h.id}><button type="button" className="cm-chip" style={{ width: '100%' }} onClick={() => void load(h.id)}>{h.title || 'Conversation'} <span className="muted">({h.message_count})</span></button></li>)}
              </ul>
            )}
          </div>
        ) : (
          <>
            <div className="cm-msg ai">{WELCOME}</div>
            {msgs.length === 0 && available !== false && (
              <div className="cm-suggest" aria-label="Suggested questions">
                {SUGGESTIONS.map(q => <button key={q} type="button" className="cm-chip" onClick={() => void send(q)} disabled={busy}>{q}</button>)}
              </div>
            )}
            {msgs.map(m => (
              <div key={m.key} className={`cm-msg ${m.role}`} {...(m.error ? { role: 'alert' } : {})}>
                {m.pending ? <span className="cm-typing" role="status" aria-label="CoverMate AI is typing"><i /><i /><i /></span> : m.content}
                {m.role === 'ai' && !m.pending && (
                  <>
                    {m.notice && <div className="cm-note">{m.notice}</div>}
                    <div className="cm-tools">
                      {!m.error && <button type="button" onClick={() => void copy(m)}><Copy size={13} aria-hidden="true" /> {copied === m.key ? 'Copied' : 'Copy'}</button>}
                      {m === lastAi && !busy && <button type="button" onClick={retry}><RefreshCw size={13} aria-hidden="true" /> Retry</button>}
                    </div>
                    {m === lastAi && !m.error && focus && (focus.policy_number || focus.claim_number) && (
                      <div className="cm-links">
                        {focus.policy_number && <Link to="/student/policies" onClick={close}>Policy {focus.policy_number}</Link>}
                        {focus.claim_id && focus.claim_number && <Link to={`/student/claims/${focus.claim_id}`} onClick={close}>Claim {focus.claim_number}</Link>}
                      </div>
                    )}
                  </>
                )}
              </div>
            ))}
            {available === false && msgs.length === 0 && <div className="cm-alert" role="alert">{UNAVAILABLE}</div>}
          </>
        )}
      </div>
      <div className="cm-foot">
        <form onSubmit={submit}>
          <label htmlFor="cm-input" className="sr-only">Your question</label>
          <textarea id="cm-input" ref={inputRef} value={text} onChange={e => setText(e.target.value)} onKeyDown={onKey} rows={1} maxLength={1500} placeholder="Ask anything about insurance" disabled={available === false} />
          <button type="submit" disabled={busy || !text.trim() || available === false} aria-label="Send message"><Send size={18} aria-hidden="true" /></button>
        </form>
        <p className="cm-disclaimer">AI can make mistakes. Your official premium, coverage and claim figures are on your Policy and Claim pages. Simulated academic prototype.</p>
      </div>
    </section>
  );
}
